  {
#pragma omp loop reduction(+:total)
    for (int x = 0; x < N; ++x) {
      total += a[x] + b[x];
    }
#pragma omp for
    for (int x = 0; x < N; ++x) {
      num_threads[x] = omp_get_num_threads();
    }
  }

  for (int x = 0; x < N; ++x) {
    expect_total += a[x] + b[x];
  }

  for (int x = 1; x < N; ++x) {
