 4  //
 5  // This test checks the parallel master taskloop directive. The test performs
 6  // simple operations on an int array which are then checked for correctness.
 7  //
 8  ////===----------------------------------------------------------------------===//
 9  #include <assert.h>
10  #include <omp.h>
11  #include <stdio.h>
12  #include <stdlib.h>
13  #include "ompvv.h"
14
15  #define N 1024
16
17  int test_parallel_master_taskloop() {
18    OMPVV_INFOMSG("test_parallel_master_taskloop");
19    int errors = 0;
20    int num_threads = -1;
21    int x[N];
22    int y[N];
23    int z[N];
24
25    for (int i = 0; i < N; i++) {
26      x[i] = 1;
27      y[i] = i + 1;
28      z[i] = 2*(i + 1);
29    }
30
31  #pragma omp parallel master taskloop num_threads(OMPVV_NUM_THREADS_HOST) shared(x, y, z, num_threads)
32    for (int i = 0; i < N; i++) {
33      x[i] += y[i]*z[i];
34      if (i == 0) {
35        num_threads = omp_get_num_threads();
36      }
37    }
38
39    for (int i = 0; i < N; i++) {
40      OMPVV_TEST_AND_SET_VERBOSE(errors, x[i] != 1 + (y[i]*z[i]));
41    }
42
43    OMPVV_WARNING_IF(num_threads == 1, "Test ran with one thread, so parallelism of taskloop can't be guaranteed.");
44    OMPVV_ERROR_IF(num_threads < 1, "Test returned an invalid number of threads.");
45    OMPVV_TEST_AND_SET_VERBOSE(errors, num_threads < 1);
46
47    return errors;
48  }
49
50
51  int main() {
52    int errors = 0;
53
54    OMPVV_TEST_OFFLOADING;
55
56    OMPVV_TEST_AND_SET_VERBOSE(errors, test_parallel_master_taskloop());
57
58    OMPVV_REPORT_AND_RETURN(errors);
59  }

