 2  //
 3  // OpenMP API Version 5.0 Nov 2018
 4  //
 5  // This is a test of the simd construct with an 'if' clause specified.
 6  // When the statement in the 'if' clause evaluates to true,
 7  // the preferred number of iterations secified in the simdlen clause
 8  // will run concurrently. When the 'if' clause evaluates to be false,
 9  // the number of iterations that will execute concurrently is one.
10  //
11  ////===--------------------------------------------------------------===//
12
13  #include <stdlib.h>
14  #include <stdio.h>
15  #include <omp.h>
16  #include "ompvv.h"
17
18  #define N 1024
19
20  int test_simd_if () {
21     int errors = 0;
22     int i;
23     int b[N], c[N];
24
25     struct new_struct {
26        int a[N];
27     };
28
29     struct new_struct struct_t;
30
31     for (i = 0; i < N; i++ ) {
32        struct_t.a[i] = i;
33        b[i] = i + 5;
34        c[i] = 0;
35     }
36
37     int k = N;
38
39     #pragma omp simd simdlen(64) if(k == N) // simdlen specifies # of concurrent iterations
40        for (i = 0; i < N; i++) {
41           c[i] = struct_t.a[i] * b[i];
42        }
43
44     for (i = 0; i < N; i++) {
45        OMPVV_TEST_AND_SET_VERBOSE(errors, c[i] != (struct_t.a[i] * b[i]));
46     }
47
48     #pragma omp simd simdlen(64) if(k != N)
49        for (i = 0; i < N; i++) {
50           c[i] = struct_t.a[i] * 2 * b[i];
51        }
52
53     for (i = 0; i < N; i++) {
54        OMPVV_TEST_AND_SET_VERBOSE(errors, c[i] != (struct_t.a[i] * 2 * b[i]));
55     }
56
57     return errors;
58  }
59
60
61  int main () {
62     int errors = 0;
63
64     OMPVV_WARNING("Vectorization resulting from the construct cannot be guaranteed");
65     OMPVV_TEST_AND_SET_VERBOSE(errors, test_simd_if());
66     OMPVV_REPORT_AND_RETURN(errors);
67  }

