 2  //
 3  // OpenMP API Version 5.0 Nov 2018
 4  //
 5  // This test checks for support of the nontemporal clause on a simd construct.
 6  // The nontemporal clause indicates that accesses to the storage location of list
 7  // items have low temporal locality across the iterations in which those storage
 8  // locations are accessed.
 9  //
10  ////===-------------------------------------------------------------------------------===//
11
12  #include <omp.h>
13  #include <stdio.h>
14  #include <stdlib.h>
15  #include "ompvv.h"
16
17  #define N 1028
18  #define STRIDE_LEN 100
19
20  int test_simd_nontemporal() {
21     int errors = 0;
22     int i;
23     int a[N], b[N], c[N];
24
25     for (i = 0; i < N; i++) {
26        a[i] = 10;
27        b[i] = i;
28        c[i] = 2 * i;
29     }
30
31     #pragma omp simd nontemporal (a, b, c)
32        for (i = 0; i < N; i += STRIDE_LEN) {
33           a[i] = b[i] * c[i];
34        }
35
36     for (i = 0; i < N; i++) {
37        if (i % STRIDE_LEN == 0) {
38           OMPVV_TEST_AND_SET(errors, a[i] != (b[i] * c[i]));
39        } else {
40           OMPVV_TEST_AND_SET(errors, a[i] != 10);
41        }
42     }
43
44     return errors;
45  }
46
47  int main () {
48     int errors = 0;
49     OMPVV_TEST_AND_SET_VERBOSE(errors, test_simd_nontemporal())
50     OMPVV_REPORT_AND_RETURN(errors);
51  }
