 1  //===--- test_taskgroup_task_reduction.c ------------------------------------===//
 2  //
 3  // OpenMP API Version 5.0 Nov 2018
 4  //
 5  // This test checks the taskgroup construct with the task_reduction clause.
 6  // It uses a linked list data structure which is then traversed and reduced
 7  // over by a taskgroup. This test is based on a OpenMP 5.0 official example.
 8  //
 9  ////===----------------------------------------------------------------------===//
10  #include <stdlib.h>
11  #include <stdio.h>
12  #include <omp.h>
13  #include "ompvv.h"
14
15  #define N 128
16
17  typedef struct node_tag {
18    int val;
19    struct node_tag *next;
20  } node_t;
21
22  int linked_list_sum(node_t *p)
23  {
24    int result = 0;
25  #pragma omp taskgroup task_reduction(+: result)
26    {
27      node_t* temp = p;
28      while(temp != 0) {
29  #pragma omp task in_reduction(+: result)
30        result += temp->val;
31        temp = temp->next;
32      }
33    }
34    return result;
35  }
36
37  int seq_linked_list_sum(node_t *p)
38  {
39    int result = 0;
40    node_t* temp = p;
41    while(temp != 0) {
42      result += temp->val;
43      temp = temp->next;
44    }
45    return result;
46  }
47
48
49  int main(int argc, char *argv[]) {
50    int errors = 0, result = -1;
51    node_t* root = (node_t*) malloc(sizeof(node_t));
52    root->val = 1;
53
54    node_t* temp = root;
55
56    for(int i = 2; i <= N; ++i) {
57      temp->next = (node_t*) malloc(sizeof(node_t));
58      temp = temp->next;
59      temp->val = i;
60    }
61
62    temp->next = 0;
63
64  #pragma omp parallel shared(result) num_threads(OMPVV_NUM_THREADS_HOST)
65  #pragma omp single
66    {
67      result = linked_list_sum(root);
68    }
69
70    OMPVV_TEST_AND_SET_VERBOSE(errors, result != seq_linked_list_sum(root));
71
72    while (root) {
73      temp = root;
74      root = root->next;
75      free(temp);
76    }
77
78    OMPVV_REPORT_AND_RETURN(errors);
79  }

