        int sum = 0;

        #pragma omp task shared(sum) default(private)
        {
        #pragma omp target map(tofrom: sum, test_num)
        {
                int test_num = 2;
                sum += test_num;

        }
        }
        OMPVV_TEST_AND_SET_VERBOSE(errors, sum != 2);
        OMPVV_INFOMSG_IF(sum == 1, "Did not use variable delcared in task region");
        return errors;
}

